"use strict";

/* ============================================================
   بيانات التطبيق
   ============================================================ */
const DATA = (typeof WORD_DATA !== "undefined") ? WORD_DATA : null;

const STORE = {
  saved: "vocab_saved",
  missed: "vocab_missed",
  quiz: "vocab_quiz",
};

const state = {
  currentSection: null,
  searchTerm: "",
  savedKeys: new Set(),
  missed: {},
  lastQuiz: null,
  fc: { words: [], index: 0, flipped: false, direction: "en2ar" },
  quiz: {
    questions: [],
    index: 0,
    score: 0,
    answered: false,
    selected: null,
  },
};

/* ---------------- أدوات مساعدة ---------------- */
function loadJSON(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch (e) {
    return fallback;
  }
}
function saveJSON(key, val) {
  try { localStorage.setItem(key, JSON.stringify(val)); } catch (e) {}
}

function esc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function escRe(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function keyOf(w) {
  return (w.en || "") + "\u00A6" + (w.ar || "");
}

