function sectionTitle(en) {
  return SECTION_AR_TITLES[en] || en;
}

function toast(msg) {
  const t = document.getElementById("toast");
  t.textContent = msg;
  t.hidden = false;
  clearTimeout(t._timer);
  t._timer = setTimeout(() => { t.hidden = true; }, 2200);
}

function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/* ============================================================
   بناء قوائم الكلمات المسطحة
   ============================================================ */
let ALL_WORDS = [];
let ALL_SECTIONS = [];
let ALL_ITEMS = [];
let stats = { words: 0, examples: 0, sections: 0 };

function buildData() {
  if (!DATA) return;
  stats.sections = DATA.stats ? DATA.stats.sections : DATA.sections.length;
  stats.examples = DATA.stats ? DATA.stats.examples_total : 0;

  ALL_SECTIONS = DATA.sections.map((sec, si) => {
    const words = sec.words
      .filter(w => !w.id || w.id !== null)   // include all
      .map(w => ({
        key: keyOf(w),
        en: w.en,
        ar: w.ar,
        id: w.id,
        section: si,
        subs: w.subs || [],
        examples: w.examples || [],
      }));
    return { en: sec.title_en, si, count: words.length, total: words.length + words.reduce((n, w) => n + (w.subs ? w.subs.length : 0), 0), words };
  });

  ALL_WORDS = [];
  ALL_SECTIONS.forEach(sec => {
    sec.words.forEach(w => {
      ALL_WORDS.push(w);
      w.sectionName = sectionTitle(sec.en);
    });
  });
  stats.words = ALL_WORDS.length;
  stats.subs = ALL_WORDS.reduce((n, w) => n + (w.subs ? w.subs.length : 0), 0);
  ALL_ITEMS = expandStudyWords(ALL_WORDS);
}

/* يعيد قائمة مسطّحة تضم الكلمات الرئيسية مع كل الكلمات الفرعية
   (تستخدمها البطاقات والاختبار كي تشمل «جميع الكلمات») */
function expandStudyWords(words) {
  const seen = new Set();
  const out = [];
  words.forEach(w => {
    if (!w || seen.has(w.key)) return;
    seen.add(w.key);
    out.push({ key: w.key, en: w.en, ar: w.ar, examples: w.examples, isSub: false, parent: w });
    (w.subs || []).forEach(s => {
      const sk = w.key + "\u00A6sub\u00A6" + s.en + "\u00A6" + s.ar;
      out.push({ key: sk, en: s.en, ar: s.ar, examples: s.examples, isSub: true, parent: w });
    });
  });
  return out;
}

/* ============================================================
   المحفوظات
   ============================================================ */
function loadState() {
  state.savedKeys = new Set(loadJSON(STORE.saved, []));
  state.missed = loadJSON(STORE.missed, {});
  state.lastQuiz = loadJSON(STORE.quiz, null);
}

function persistSaved() {
  saveJSON(STORE.saved, [...state.savedKeys]);
  updateSavedBadge();
}

function updateSavedBadge() {
  document.getElementById("saved-count").textContent = state.savedKeys.size;
}

function isSaved(w) { return state.savedKeys.has(keyOf(w)); }

function toggleSaved(w) {
  const k = keyOf(w);
  if (state.savedKeys.has(k)) state.savedKeys.delete(k);
  else state.savedKeys.add(k);
  persistSaved();
  const saved = state.savedKeys.has(k);
  toast(saved ? "تم حفظ الكلمة ⭐" : "تمت إزالة الحفظ");
  // تحديث جميع البطاقات المفتوحة لهذه الكلمة
  document.querySelectorAll(`[data-key="${CSS.escape(k)}"]`).forEach(c => {
    c.classList.toggle("saved", saved);
    const btn = c.querySelector(".bookmark-btn");
    if (btn) { btn.classList.toggle("saved", saved); btn.textContent = saved ? "⭐" : "☆"; }
    const main = c.querySelector(".word-main");
    if (main) {
      const badge = main.querySelector(".saved-badge");
      const ar = main.querySelector(".word-ar");
      if (saved && !badge && ar) {
        const b = document.createElement("span");
        b.className = "saved-badge";
        b.textContent = "✓ تم الحفظ";
        ar.insertAdjacentElement("afterend", b);
      } else if (!saved && badge) {
        badge.remove();
      }
    }
  });
}

/* ============================================================
   القاموس
   ============================================================ */
function renderSections() {
  const list = document.getElementById("sections-list");
  const dlist = document.getElementById("sections-drawer-list");
  list.innerHTML = "";
  dlist.innerHTML = "";
  const makeAllBtn = () => {
    const btn = document.createElement("button");
    btn.dataset.section = "-1";
    btn.innerHTML = `<span>📚 جميع الكلمات</span><span class="sec-count">${ALL_WORDS.length}</span>`;
    btn.addEventListener("click", () => selectSection(-1));
    return btn;
  };
  const allLi = document.createElement("li");
  allLi.appendChild(makeAllBtn());
  list.appendChild(allLi);
  const dAllLi = document.createElement("li");
  dAllLi.appendChild(makeAllBtn());
  dlist.appendChild(dAllLi);
  ALL_SECTIONS.forEach((sec, i) => {
    const makeBtn = () => {
      const btn = document.createElement("button");
      btn.dataset.section = i;
      btn.innerHTML = `<span>${esc(sectionTitle(sec.en))}</span><span class="sec-count">${sec.count}</span>`;
      btn.addEventListener("click", () => selectSection(i));
      return btn;
    };
    const li = document.createElement("li");
    li.appendChild(makeBtn());
    list.appendChild(li);
    const dli = document.createElement("li");
    dli.appendChild(makeBtn());
    dlist.appendChild(dli);
  });
}

function selectSection(si) {
  state.currentSection = (si < 0) ? null : si;
  document.querySelectorAll("[data-section]").forEach(b => {
    b.classList.toggle("active", Number(b.dataset.section) === si);
  });
  renderDictionary();
  closeSectionsDrawer();
  if (state.currentSection === null) {
    document.getElementById("dict-grid").scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

function openSectionsDrawer() {
  const d = document.getElementById("sections-drawer");
  const o = document.getElementById("sections-drawer-overlay");
  o.hidden = false;
  // force reflow so the closing transition can replay on re-open
  void d.offsetWidth;
  d.classList.add("open");
  o.classList.add("open");
  d.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden";
}

function closeSectionsDrawer() {
  const d = document.getElementById("sections-drawer");
  const o = document.getElementById("sections-drawer-overlay");
  d.classList.remove("open");
  o.classList.remove("open");
  d.setAttribute("aria-hidden", "true");
  document.body.style.overflow = "";
  setTimeout(() => { if (!o.classList.contains("open")) o.hidden = true; }, 300);
}

function renderDictionary() {
  const grid = document.getElementById("dict-grid");
  const empty = document.getElementById("dict-empty");
  const term = state.searchTerm.trim().toLowerCase();

  let words = ALL_WORDS;
  if (state.currentSection !== null) {
    words = words.filter(w => w.section === state.currentSection);
  }
  if (term) {
    words = words.filter(w => {
      if (w.en.toLowerCase().includes(term)) return true;
      if ((w.ar || "").includes(term)) return true;
      if (w.subs.some(s => s.en.toLowerCase().includes(term) || (s.ar || "").includes(term))) return true;
      return false;
    });
  }

  empty.hidden = words.length > 0;
  grid.innerHTML = words.map(wordCardHTML).join("");
  grid.querySelectorAll(".bookmark-btn").forEach(b => {
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      const key = b.closest(".word-card").dataset.key;
      const w = findWordByKey(key);
      if (w) toggleSaved(w);
    });
  });
  grid.querySelectorAll(".examples-toggle").forEach(t => {
    t.addEventListener("click", () => {
      const w = findWordByKey(t.closest(".word-card").dataset.key);
      if (w) openExamplesModal(w);
    });
  });
  grid.querySelectorAll(".sub-chip").forEach(c => {
    c.addEventListener("click", () => {
      const w = findWordByKey(c.closest(".word-card").dataset.key);
      if (w) openSubExamplesModal(w, Number(c.dataset.sub));
    });
  });
}

/* ============================================================
   نافذة الأمثلة (Modal)
   ============================================================ */
function examplesListHTML(examples) {
  return examples.map((e, i) => {
    const safeEn = esc(e.en).replace(/'/g, "\\'");
    return `
    <div class="example-item">
      <div class="example-en"><span class="example-num">${i + 1}</span>${esc(e.en)}</div>
      <div class="example-ar">${esc(e.ar)}</div>
      <button class="sound-btn" title="استمع للنطق" onclick="speak('${safeEn}')">🔊</button>
    </div>`;
  }).join("");
}

function openExamplesModal(w) {
  const overlay = document.getElementById("modal-overlay");
  if (!overlay) return;
  const ex = w.examples || [];
  document.getElementById("modal-title").innerHTML =
    `أمثلة "${esc(w.en)}" <span class="modal-sub">${esc(w.ar)}</span>`;
  document.getElementById("modal-body").innerHTML =
    ex.length
      ? `<div class="examples-list">${examplesListHTML(ex)}</div>`
      : `<div class="no-examples">لا توجد أمثلة متاحة لهذه الكلمة</div>`;
  overlay.hidden = false;
  document.body.classList.add("modal-open");
}

function openSubExamplesModal(w, subIdx) {
  const overlay = document.getElementById("modal-overlay");
  if (!overlay) return;
  const s = w.subs[subIdx];
  if (!s) return;
  const ex = s.examples || [];
  document.getElementById("modal-title").innerHTML =
    `أمثلة "${esc(s.en)}" <span class="modal-sub">${esc(s.ar)}</span>`;
  document.getElementById("modal-body").innerHTML =
    ex.length
      ? `<div class="examples-list">${examplesListHTML(ex)}</div>`
      : `<div class="no-examples">لا توجد أمثلة متاحة لهذه الكلمة</div>`;
  overlay.hidden = false;
  document.body.classList.add("modal-open");
}

function closeExamplesModal() {
  const overlay = document.getElementById("modal-overlay");
  if (overlay) overlay.hidden = true;
  document.body.classList.remove("modal-open");
}

function wordCardHTML(w) {
  const saved = isSaved(w);
  const hasEx = w.examples && w.examples.length > 0;
  const subChips = w.subs.map((s, i) => {
    const hasSubEx = s.examples && s.examples.length > 0;
    const exDot = hasSubEx ? `<span class="chip-ex">• أمثلة ${s.examples.length}</span>` : "";
    const safeSubEn = esc(s.en).replace(/'/g, "\\'");
    return `
      <div class="sub-chip-wrap">
        <button class="sub-chip" data-sub="${i}">
          <b>${esc(s.en)}</b> <span class="chip-ar">${esc(s.ar)}</span>${exDot}
        </button>
        <button class="sound-btn sub-sound-btn" title="استمع للنطق" onclick="event.stopPropagation(); speak('${safeSubEn}')">🔊</button>
      </div>`;
  }).join("");

  const idBadge = (w.id != null) ? `<span class="word-id">#${w.id}</span>` : "";
  const savedBadge = saved ? `<span class="saved-badge">✓ تم الحفظ</span>` : "";

  const exSection = hasEx ? `
    <button class="examples-toggle" data-count="${w.examples.length}" title="عرض الأمثلة في نافذة">
      📄 عرض الأمثلة <span>(${w.examples.length})</span>
    </button>` : `<div class="no-examples">لا توجد أمثلة متاحة لهذه الكلمة</div>`;

  const safeEn = esc(w.en).replace(/'/g, "\\'");

  return `
  <article class="word-card ${saved ? "saved" : ""}" data-key="${esc(w.key)}">
    <div class="word-card-head">
      ${idBadge}
      <div class="word-main">
        <span class="word-en">${esc(w.en)}</span>
        <span class="word-ar">${esc(w.ar)}</span>
        ${savedBadge}
        <small class="word-section">${esc(w.sectionName || "")}</small>
      </div>
      <div style="display:flex; gap:6px; align-items:center; flex-shrink:0;">
        <button class="sound-btn" title="استمع للنطق" onclick="speak('${safeEn}')">🔊</button>
        <button class="bookmark-btn ${saved ? "saved" : ""}" title="حفظ الكلمة">${saved ? "⭐" : "☆"}</button>
      </div>
    </div>
    <div class="word-subs">${subChips}</div>
    ${exSection}
  </article>`;
}

function findWordByKey(key) {
  return ALL_WORDS.find(w => w.key === key);
}

function wordCardHTMLForSaved(w) {
  return wordCardHTML(w);
}

function renderSaved() {
  const grid = document.getElementById("saved-grid");
  const empty = document.getElementById("saved-empty");
  const savedWords = ALL_WORDS.filter(w => state.savedKeys.has(w.key));
  empty.hidden = savedWords.length > 0;
  grid.innerHTML = savedWords.map(wordCardHTML).join("");
  grid.querySelectorAll(".bookmark-btn").forEach(b => {
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      const key = b.closest(".word-card").dataset.key;
      const w = findWordByKey(key);
      if (w) {
        toggleSaved(w);
        renderSaved();
      }
    });
  });
  grid.querySelectorAll(".examples-toggle").forEach(t => {
    t.addEventListener("click", () => {
      const w = findWordByKey(t.closest(".word-card").dataset.key);
      if (w) openExamplesModal(w);
    });
  });
  grid.querySelectorAll(".sub-chip").forEach(c => {
    c.addEventListener("click", () => {
      const w = findWordByKey(c.closest(".word-card").dataset.key);
      if (w) openSubExamplesModal(w, Number(c.dataset.sub));
    });
  });
}

/* ============================================================
   التنقل بين الأقسام
   ============================================================ */
function switchView(view) {
  document.querySelectorAll(".view").forEach(v => v.classList.remove("active"));
  document.getElementById("view-" + view).classList.add("active");
  document.querySelectorAll(".tab").forEach(t => t.classList.toggle("active", t.dataset.view === view));
  if (view === "saved") renderSaved();
  if (view === "flashcards") populateSectionSelect("fc-section");
  if (view === "quiz") {
    populateSectionSelect("quiz-section");
    updateQuizLastScore();
  }
}

function populateSectionSelect(id) {
  const sel = document.getElementById(id);
  const current = sel.value;
  sel.innerHTML = ALL_SECTIONS.map((s, i) => `<option value="${i}">${esc(sectionTitle(s.en))} (${s.total})</option>`).join("");
  if (current && ALL_SECTIONS[current]) sel.value = current;
}

/* ============================================================
   نطاق الاختبار / البطاقات
   ============================================================ */
function resolveScopeWords(scope, sectionSel) {
  if (scope === "all") return ALL_WORDS;
  if (scope === "saved") return ALL_WORDS.filter(w => state.savedKeys.has(w.key));
  if (scope === "section") {
    const si = Number(sectionSel.value);
    return ALL_WORDS.filter(w => w.section === si);
  }
  if (scope === "missed") {
    const keys = Object.keys(state.missed).filter(k => state.missed[k] > 0);
    return ALL_ITEMS.filter(it => keys.includes(it.key));
  }
  return ALL_WORDS;
}

function toggleScopeSection(scope, selectId) {
  document.getElementById(selectId).hidden = scope !== "section";
}

/* ============================================================
   البطاقات التعليمية
   ============================================================ */
function startFlashcards() {
  const scope = document.getElementById("fc-scope").value;
  const words = expandStudyWords(resolveScopeWords(scope, document.getElementById("fc-section")));
  if (words.length === 0) { toast("لا توجد كلمات في هذا النطاق"); return; }
  const count = Math.max(1, parseInt(document.getElementById("fc-count").value, 10) || words.length);
  state.fc.direction = document.getElementById("fc-direction").value;
  state.fc.words = shuffle(words).slice(0, count);
  state.fc.index = 0;
  state.fc.flipped = false;
  document.getElementById("flash-card").classList.remove("flipped");
  document.querySelector(".flash-settings").hidden = true;
  document.getElementById("fc-area").hidden = false;
  renderFlashcard();
}

function renderFlashcard() {
  const w = state.fc.words[state.fc.index];
  const front = document.getElementById("fc-front-text");
  const backText = document.getElementById("fc-back-text");
  const backAr = document.getElementById("fc-back-ar");
  const backEx = document.getElementById("fc-back-ex");

  const dir = state.fc.direction;
  front.textContent = dir === "en2ar" ? w.en : w.ar;
  backText.textContent = dir === "en2ar" ? w.ar : w.en;
  backAr.textContent = dir === "en2ar" ? w.en : "";
  const ex = (w.examples && w.examples[0]);
  backEx.innerHTML = ex
    ? (dir === "en2ar"
        ? `<b>${esc(ex.en)}</b> — ${esc(ex.ar)}`
        : `<b>${esc(ex.ar)}</b> — ${esc(ex.en)}`)
    : "";
  document.getElementById("fc-progress").textContent = (state.fc.index + 1) + " / " + state.fc.words.length;
}

function fcFlip() {
  state.fc.flipped = !state.fc.flipped;
  document.getElementById("flash-card").classList.toggle("flipped", state.fc.flipped);
}

function fcPrev() {
  if (state.fc.index > 0) {
    state.fc.index--;
    state.fc.flipped = false;
    document.getElementById("flash-card").classList.remove("flipped");
    renderFlashcard();
  }
}

function fcNext() {
  if (state.fc.index < state.fc.words.length - 1) {
    state.fc.index++;
    state.fc.flipped = false;
    document.getElementById("flash-card").classList.remove("flipped");
    renderFlashcard();
  } else {
    toast("انتهت البطاقات! 🎉");
    document.querySelector(".flash-settings").hidden = false;
    document.getElementById("fc-area").hidden = true;
  }
}

/* ============================================================
   الاختبار
   ============================================================ */
function buildQuizPool() {
  const scope = document.getElementById("quiz-scope").value;
  const words = expandStudyWords(resolveScopeWords(scope, document.getElementById("quiz-section")));
  return words;
}

function updateQuizLastScore() {
  const el = document.getElementById("quiz-last-score");
  if (state.lastQuiz) {
    const pct = state.lastQuiz.total ? Math.round((state.lastQuiz.score / state.lastQuiz.total) * 100) : 0;
    el.textContent = `نتيجة آخر اختبار: ${state.lastQuiz.score} / ${state.lastQuiz.total} (${pct}%)`;
  } else {
    el.textContent = "";
  }
}

function startQuiz() {
  const type = document.getElementById("quiz-type").value;
  const pool = buildQuizPool();
  if (pool.length === 0) { toast("لا توجد كلمات في هذا النطاق"); return; }
  let count = Math.max(1, parseInt(document.getElementById("quiz-count").value, 10) || 10);

  let questions;
  if (type === "sentence") {
    questions = buildSentenceQuestions(pool, count);
  } else {
    const dirSetting = document.getElementById("quiz-direction").value;
    count = Math.min(count, pool.length);
    questions = buildTranslationQuestions(pool, count, dirSetting);
  }
  if (questions.length === 0) { toast("لا توجد أسئلة مناسبة في هذا النطاق"); return; }

  state.quiz.questions = questions;
  state.quiz.index = 0;
  state.quiz.score = 0;
  state.quiz.answered = false;

  document.getElementById("quiz-setup").hidden = true;
  document.getElementById("quiz-result").hidden = true;
  document.getElementById("quiz-area").hidden = false;
  renderQuizQuestion();
}

function buildTranslationQuestions(pool, count, dirSetting) {
  // distractors drawn from the WHOLE vocabulary (main + sub words), not just the current pool
  const globalEn = [];
  const globalAr = [];
  ALL_WORDS.forEach(w => {
    globalEn.push(w.en); globalAr.push(w.ar);
    (w.subs || []).forEach(s => { globalEn.push(s.en); globalAr.push(s.ar); });
  });

  return shuffle(pool).slice(0, count).map(it => {
    const dir = dirSetting === "mixed" ? (Math.random() < 0.5 ? "en2ar" : "ar2en") : dirSetting;
    const correct = dir === "en2ar" ? it.ar : it.en;
    const distractVals = dir === "en2ar" ? globalAr : globalEn;
    const others = shuffle(distractVals.filter(v => v !== correct)).slice(0, 3);
    const options = shuffle([correct, ...others]);
    return { type: "translation", w: it, correct, options, dir };
  });
}

function buildSentenceQuestions(pool, count) {
  const globalEn = [];
  ALL_WORDS.forEach(w => {
    globalEn.push(w.en);
    (w.subs || []).forEach(s => globalEn.push(s.en));
  });

  const seen = new Set();
  const candidates = [];
  for (const it of shuffle(pool)) {
    const term = String(it.en || "").trim();
    if (!term || /\s{2,}/.test(term)) continue;
    const re = new RegExp("\\b" + escRe(term) + "\\b", "i");
    const ex = (it.examples || []).find(e => e.en && e.ar && re.test(e.en));
    if (!ex) continue;
    const sentKey = ex.en.toLowerCase();
    if (seen.has(sentKey)) continue;
    seen.add(sentKey);
    candidates.push({ it, sentence: ex.en, sentenceAr: ex.ar, re });
    if (candidates.length >= count * 8) break;
  }

  return shuffle(candidates).slice(0, count).map(c => {
    const correct = c.it.en;
    const others = shuffle(globalEn.filter(v => v.toLowerCase() !== correct.toLowerCase())).slice(0, 3);
    const options = shuffle([correct, ...others]);
    return {
      type: "sentence",
      w: c.it,
      correct,
      options,
      sentence: c.sentence.replace(c.re, () => "_____"),
      sentenceFull: c.sentence,
      sentenceAr: c.sentenceAr,
    };
  });
}

function renderQuizQuestion() {
  const q = state.quiz.questions[state.quiz.index];
  document.getElementById("quiz-progress-text").textContent =
    `السؤال ${state.quiz.index + 1} من ${state.quiz.questions.length}`;
  document.getElementById("quiz-progress-fill").style.width =
    ((state.quiz.index) / state.quiz.questions.length) * 100 + "%";

  const qEl = document.getElementById("quiz-question");
  const subEl = document.querySelector(".quiz-question-sub");
  if (q.type === "sentence") {
    qEl.innerHTML = `<div class="quiz-sentence">${esc(q.sentence).replace(/_____/g, '<span class="quiz-blank">_____</span>')}</div>`;
    subEl.textContent = "اختر الكلمة المناسبة لإكمال الجملة";
  } else {
    const dir = q.dir;
    qEl.textContent = dir === "en2ar" ? q.w.en : q.w.ar;
    subEl.textContent =
      dir === "en2ar" ? "اختر الترجمة العربية الصحيحة" : "اختر الكلمة الإنجليزية الصحيحة";
  }

  const optsEl = document.getElementById("quiz-options");
  optsEl.innerHTML = q.options.map((opt, i) =>
    `<button class="quiz-option" data-i="${i}">${esc(opt)}</button>`
  ).join("");

  const fb = document.getElementById("quiz-feedback");
  fb.textContent = "";
  fb.className = "quiz-feedback";
  document.getElementById("btn-quiz-next").hidden = true;

  optsEl.querySelectorAll(".quiz-option").forEach(btn => {
    btn.addEventListener("click", () => answerQuiz(btn));
  });
  state.quiz.answered = false;
}

function answerQuiz(btn) {
  if (state.quiz.answered) return;
  state.quiz.answered = true;
  const q = state.quiz.questions[state.quiz.index];
  const chosen = q.options[Number(btn.dataset.i)];
  const isCorrect = chosen === q.correct;
  const fb = document.getElementById("quiz-feedback");

  document.querySelectorAll(".quiz-option").forEach(b => b.disabled = true);
  document.querySelectorAll(".quiz-option").forEach(b => {
    if (b.textContent === q.correct) b.classList.add("correct");
  });

  if (isCorrect) {
    state.quiz.score++;
    if (q.type === "sentence") {
      fb.innerHTML = `✅ إجابة صحيحة!<br><div class="quiz-sentence">${esc(q.sentenceFull)}</div>`;
    } else {
      fb.textContent = "✅ إجابة صحيحة!";
    }
    fb.className = "quiz-feedback good";
  } else {
    btn.classList.add("wrong");
    if (q.type === "sentence") {
      fb.innerHTML = `❌ إجابة خاطئة.<br>الكلمة الصحيحة: <b>${esc(q.correct)}</b><br><div class="quiz-sentence">${esc(q.sentenceFull)}</div>`;
    } else {
      fb.innerHTML = `❌ إجابة خاطئة.<br><b>${esc(q.correct)}</b>`;
    }
    fb.className = "quiz-feedback bad";
    state.missed[q.w.key] = (state.missed[q.w.key] || 0) + 1;
    saveJSON(STORE.missed, state.missed);
  }

  const last = state.quiz.index === state.quiz.questions.length - 1;
  const nextBtn = document.getElementById("btn-quiz-next");
  nextBtn.textContent = last ? "عرض النتيجة" : "السؤال التالي";
  nextBtn.hidden = false;
}

function nextQuiz() {
  if (state.quiz.index < state.quiz.questions.length - 1) {
    state.quiz.index++;
    renderQuizQuestion();
  } else {
    showQuizResult();
  }
}

function showQuizResult() {
  document.getElementById("quiz-area").hidden = true;
  const result = document.getElementById("quiz-result");
  result.hidden = false;

  const total = state.quiz.questions.length;
  const score = state.quiz.score;
  const pct = Math.round((score / total) * 100);

  state.lastQuiz = { score, total, when: Date.now() };
  saveJSON(STORE.quiz, state.lastQuiz);

  const msg = pct >= 90 ? "ممتاز! 🏆" : pct >= 70 ? "جيد جدًا! 👏" : pct >= 50 ? "جيد، واصل التدريب 💪" : "تحتاج إلى مزيد من المراجعة 📚";
  document.getElementById("result-score").innerHTML =
    `<span class="big">${score} / ${total}</span> &nbsp;${pct}%`;
  document.getElementById("result-details").textContent = msg;
}

function resetQuiz() {
  document.getElementById("quiz-result").hidden = true;
  document.getElementById("quiz-area").hidden = true;
  document.getElementById("quiz-setup").hidden = false;
  updateQuizLastScore();
}

/* ============================================================
   ربط الأحداث
   ============================================================ */
function init() {
  buildData();
  loadState();

  renderSections();
  renderDictionary();

  document.querySelectorAll(".tab").forEach(t => {
    t.addEventListener("click", () => {
      if (t.id === "btn-sections-drawer") return;
      switchView(t.dataset.view);
    });
  });

  document.getElementById("dict-search").addEventListener("input", (e) => {
    state.searchTerm = e.target.value;
    renderDictionary();
  });

  // Sections drawer (mobile)
  document.getElementById("btn-sections-drawer").addEventListener("click", openSectionsDrawer);
  document.getElementById("sections-drawer-close").addEventListener("click", closeSectionsDrawer);
  document.getElementById("sections-drawer-overlay").addEventListener("click", closeSectionsDrawer);

  document.getElementById("btn-clear-saved").addEventListener("click", () => {
    if (!state.savedKeys.size) { toast("لا توجد كلمات محفوظة"); return; }
    if (confirm("هل أنت متأكد من مسح جميع الكلمات المحفوظة؟")) {
      state.savedKeys.clear();
      persistSaved();
      renderSaved();
      toast("تم مسح جميع المحفوظات");
    }
  });

  document.getElementById("btn-quiz-saved").addEventListener("click", () => {
    if (!state.savedKeys.size) { toast("لا توجد كلمات محفوظة بعد"); return; }
    document.getElementById("quiz-scope").value = "saved";
    toggleScopeSection("saved", "quiz-section");
    switchView("quiz");
    startQuiz();
    toast("اختبار من الكلمات المحفوظة ⭐");
  });

  // Flashcards
  document.getElementById("fc-scope").addEventListener("change", (e) => {
    toggleScopeSection(e.target.value, "fc-section");
  });
  document.getElementById("btn-fc-start").addEventListener("click", startFlashcards);
  document.getElementById("flash-card").addEventListener("click", fcFlip);
  document.getElementById("btn-fc-prev").addEventListener("click", fcPrev);
  document.getElementById("btn-fc-next").addEventListener("click", fcNext);
  document.getElementById("btn-fc-settings").addEventListener("click", () => {
    document.querySelector(".flash-settings").hidden = false;
    document.getElementById("fc-area").hidden = true;
  });

  // Quiz
  document.getElementById("quiz-scope").addEventListener("change", (e) => {
    toggleScopeSection(e.target.value, "quiz-section");
  });
  document.getElementById("quiz-type").addEventListener("change", (e) => {
    document.getElementById("quiz-direction-row").hidden = e.target.value !== "translation";
  });
  document.getElementById("btn-quiz-start").addEventListener("click", startQuiz);
  document.getElementById("btn-quiz-next").addEventListener("click", nextQuiz);
  document.getElementById("btn-quiz-retry").addEventListener("click", resetQuiz);
  document.getElementById("btn-quiz-back").addEventListener("click", () => {
    document.getElementById("quiz-area").hidden = true;
    document.getElementById("quiz-result").hidden = true;
    document.getElementById("quiz-setup").hidden = false;
    updateQuizLastScore();
  });

  // Modal
  document.getElementById("modal-close").addEventListener("click", closeExamplesModal);
  document.getElementById("modal-overlay").addEventListener("click", (e) => {
    if (e.target === document.getElementById("modal-overlay")) closeExamplesModal();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      if (document.getElementById("sections-drawer-overlay").classList.contains("open")) {
        closeSectionsDrawer();
        return;
      }
      closeExamplesModal();
    }
  });
}

document.addEventListener("DOMContentLoaded", init);

